enable_drop_protection.compliant:
resource "google_spanner_database" "c" {
  instance               = google_spanner_instance.c.name
  name                   = "c"
  enable_drop_protection = true
}

resource "google_spanner_instance" "c" {
  name         = "c"
  config       = "regional-australia-southeast1"
  display_name = "Test Instance C"
  num_nodes    = 1
}

enable_drop_protection.non-compliant:
resource "google_spanner_database" "nc" {
  instance               = google_spanner_instance.nc.name
  name                   = "nc"
  enable_drop_protection = false
}

resource "google_spanner_instance" "nc" {
  name         = "nc"
  config       = "regional-australia-southeast1"
  display_name = "Test Instance NC"
  num_nodes    = 1
}
